#!/usr/bin/env python3
"""Generate Go structs for the 100-column tables (sqlx db tags + GORM column tags) used by the framework runner."""
import os
MIX = ["int64", "int64", "Decimal", "float64", "string", "time.Time", "time.Time", "int64", "sql.NullString", "sql.NullInt64"]


def struct(name, table, types):
    fields = "\n".join(f'\tC{k:03d} {t} `db:"c{k:03d}" gorm:"column:c{k:03d}"`' for k, t in enumerate(types, 1))
    vals = ", ".join(f"r.C{k:03d}" for k in range(1, len(types) + 1))
    return f'''
// {name} maps {table} (generated by gen_wide.py).
type {name} struct {{
\tID int64 `db:"id" gorm:"column:id;primaryKey"`
{fields}
}}

func ({name}) TableName() string {{ return "{table}" }}

// Values returns the column values after id, in table order.
func (r *{name}) Values() []any {{ return []any{{{vals}}} }}
'''


src = "// Code generated by gen_wide.py. DO NOT EDIT.\n\npackage main\n\nimport (\n\t\"database/sql\"\n\t\"time\"\n)\n\nvar _ = time.Time{}\nvar _ = sql.NullString{}\n"
src += struct("WideInt", "t_wide_int", ["int64"] * 100)
src += struct("WideMix", "t_wide_mix", [MIX[(k - 1) % 10] for k in range(1, 101)])
open(os.path.join(os.path.dirname(__file__), "wide_gen.go"), "w").write(src)
print("generated wide_gen.go")
